begin;
-- Confirmed by management: the two daytime shifts pause from 12:00 to 14:00.
-- Only known original values are corrected. Custom schedules and all saved
-- calendars remain unchanged; draft recalculation is performed in the client.
create or replace function escala_private.warehouse_shift(p_shift jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,pg_temp as $$
declare s jsonb;v_start integer;v_end integer;v_previous integer:=-1;v_day integer:=0;v_first integer;v_total integer:=0;v_pause integer;
begin
 if jsonb_typeof(p_shift->'segments') is distinct from 'array' or jsonb_array_length(p_shift->'segments') not between 1 and 4 then raise exception 'WH_SHIFT_INVALID';end if;
 for s in select value from jsonb_array_elements(p_shift->'segments') loop
  if coalesce(s->>'start','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' or coalesce(s->>'end','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'WH_SHIFT_INVALID';end if;
  v_start:=split_part(s->>'start',':',1)::int*60+split_part(s->>'start',':',2)::int+v_day*1440;
  if v_start<v_previous then v_day:=v_day+1;v_start:=v_start+1440;end if;
  v_end:=split_part(s->>'end',':',1)::int*60+split_part(s->>'end',':',2)::int+v_day*1440;if v_end<=v_start then v_end:=v_end+1440;end if;
  v_first:=coalesce(v_first,v_start);v_total:=v_total+v_end-v_start;v_previous:=v_end;
 end loop;
 if coalesce(p_shift->>'break_minutes','')!~'^[0-9]{1,3}$' or (p_shift->>'break_minutes')::int not between 0 and 180 or v_total-(p_shift->>'break_minutes')::int not between 1 and 960 or v_previous-v_first>1440 then raise exception 'WH_SHIFT_INVALID';end if;
 if nullif(p_shift->>'break_start','') is not null then
  if (p_shift->>'break_start')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' or jsonb_array_length(p_shift->'segments')<>1 then raise exception 'WH_SHIFT_INVALID';end if;
  v_pause:=split_part(p_shift->>'break_start',':',1)::int*60+split_part(p_shift->>'break_start',':',2)::int;if v_pause<v_first then v_pause:=v_pause+1440;end if;
  if v_pause<v_first or v_pause+(p_shift->>'break_minutes')::int>v_previous then raise exception 'WH_SHIFT_INVALID';end if;
 end if;
 return jsonb_build_object('start',v_first,'end',v_previous,'minutes',v_total-(p_shift->>'break_minutes')::int);
end;
$$;
create or replace function escala_private.warehouse_issues(p_unit text,p_plan jsonb) returns jsonb language plpgsql stable set search_path=public,pg_temp as $$
#variable_conflict use_column
declare issues jsonb:='[]';c jsonb:=p_plan->'config_snapshot';d jsonb;p jsonb;s jsonb;t jsonb;v record;v_role text;v_goal int;v_count int;v_days jsonb;v_month date:=(p_plan->>'month')::date;
begin
 if nullif(c->>'anchor_date','') is null then issues:=issues||jsonb_build_array(jsonb_build_object('code','ANCHOR','message','Defina a segunda-feira de início do revezamento.','severity','ERROR'));end if;
 for d in select value from jsonb_array_elements(p_plan->'days') loop
  for p in select value from jsonb_array_elements(d->'people') where value->>'mode'='WORK' loop
   select value into s from jsonb_array_elements(c->'shifts') where value->>'id'=p->>'shift_id';
   if s is null then issues:=issues||jsonb_build_array(jsonb_build_object('code','SHIFT_MISSING','message',p->'person'->>'name'||': defina o turno.','date',d->>'date','person',p->'person'->>'id','severity','ERROR'));continue;end if;
   t:=escala_private.warehouse_shift(s);
   if (t->>'minutes')::int>(c->'rules'->>'daily_minutes')::int and not coalesce((c->'rules'->>'compensation')::boolean,false) then issues:=issues||jsonb_build_array(jsonb_build_object('code','DAILY_HOURS','message',p->'person'->>'name'||': jornada acima do limite diário configurado. Revise a compensação e o intervalo.','date',d->>'date','person',p->'person'->>'id','severity','ERROR'));end if;
   if jsonb_array_length(s->'segments')=1 and (s->>'break_minutes')::int<60 and (t->>'minutes')::int>360 then issues:=issues||jsonb_build_array(jsonb_build_object('code','BREAK','message',p->'person'->>'name'||': confira o intervalo do turno.','date',d->>'date','person',p->'person'->>'id','severity','ERROR'));end if;
  end loop;
 end loop;
 select coalesce(jsonb_agg(warehouse_day),'[]') into v_days from(select day||jsonb_build_object('_config',m.config_snapshot) as warehouse_day from escala_warehouse_months m cross join lateral jsonb_array_elements(m.days) day where m.unit=p_unit and m.month<>v_month and m.month between v_month-interval '1 month' and v_month+interval '1 month' union all select value||jsonb_build_object('_config',c) from jsonb_array_elements(p_plan->'days')) q;
 for v in with rows as(select (d->>'date')::date date,p,d->'_config' cfg,date_trunc('week',(d->>'date')::date)::date week from jsonb_array_elements(v_days) d cross join lateral jsonb_array_elements(d->'people') p),calc as(select p->'person'->>'id' id,max(p->'person'->>'name') name,week,count(*) present,count(*) filter(where p->>'mode'='UNAVAILABLE') unavailable,count(*) filter(where p->>'mode'='REST' and (extract(dow from date) in(0,6) or not exists(select 1 from escala_holidays h where h.unit=p_unit and h.date=rows.date and h.enabled and h.kind<>'OPTIONAL' and not h.operates))) rests,count(*) filter(where p->>'mode'='WORK') worked,coalesce(sum(case when p->>'mode'='WORK' then (escala_private.warehouse_shift((select s from jsonb_array_elements(cfg->'shifts') s where s->>'id'=p->>'shift_id'))->>'minutes')::int else 0 end),0) minutes from rows where date>=(c->>'anchor_date')::date group by p->'person'->>'id',week) select * from calc where week<=v_month+interval '1 month'-interval '1 day' and week+6>=v_month loop
  if v.present=7 and v.unavailable=0 and v.rests<2 then issues:=issues||jsonb_build_array(jsonb_build_object('code','WEEKLY_REST','message',v.name||': tem apenas '||v.rests||' folga na semana de '||to_char(v.week,'DD/MM/YYYY')||'. Garanta duas folgas.','date',v.week+6,'person',v.id,'severity','ERROR'));end if;
  if v.worked>5 or v.minutes>(c->'rules'->>'weekly_minutes')::int then issues:=issues||jsonb_build_array(jsonb_build_object('code','WEEKLY_HOURS','message',v.name||': dias ou horas acima do limite na semana de '||to_char(v.week,'DD/MM/YYYY')||'.','date',v.week+6,'person',v.id,'severity','ERROR'));end if;
 end loop;
 for v in with work as(select p->'person'->>'id' id,p->'person'->>'name' name,(d->>'date')::date date,escala_private.warehouse_shift(s) times from jsonb_array_elements(v_days) d cross join lateral jsonb_array_elements(d->'people') p join lateral jsonb_array_elements(d->'_config'->'shifts') s on s->>'id'=p->>'shift_id' where p->>'mode'='WORK'),bounds as(select *,date::timestamp+((times->>'start')::int)*interval '1 minute' starts,date::timestamp+((times->>'end')::int)*interval '1 minute' ends from work),ordered as(select *,lag(ends) over(partition by id order by date) previous_end from bounds) select * from ordered where date>=v_month and date<v_month+interval '1 month' and starts-previous_end<((c->'rules'->>'min_rest_minutes')::int)*interval '1 minute' loop
  issues:=issues||jsonb_build_array(jsonb_build_object('code','INTERDAY_REST','message',v.name||': intervalo entre turnos abaixo do mínimo configurado.','date',v.date,'person',v.id,'severity','ERROR'));
 end loop;
 return issues;
end;
$$;
do $fix$
declare r record;updated public.escala_warehouse_settings;c jsonb;s jsonb;shifts jsonb;p record;patch jsonb;patches jsonb:='[{"before":{"base_shift":"CHECK_PM","weeks":[[{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"REST","shift_id":null},{"mode":"WORK","shift_id":"CHECK_AM","notes":""},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}]]},"after":{"base_shift":"CHECK_PM","weeks":[[{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"REST","shift_id":null},{"mode":"WORK","shift_id":"CHECK_AM","notes":""},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}]]}},{"before":{"base_shift":"NIGHT","weeks":[[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"WORK","shift_id":"CHECK_AM","notes":""},{"mode":"REST","shift_id":null}],[{"mode":"REST","shift_id":null},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"CHECK_AM","notes":""},{"mode":"REST","shift_id":null}]]},"after":{"base_shift":"NIGHT","weeks":[[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"WORK","shift_id":"CHECK_AM","notes":""},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"WORK","shift_id":"CHECK_AM","notes":""},{"mode":"REST","shift_id":null}]]}},{"before":{"base_shift":"NIGHT","weeks":[[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"CHECK_PM","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"WORK","shift_id":"FORK_AM","notes":""},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}]]},"after":{"base_shift":"NIGHT","weeks":[[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"CHECK_PM_15","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"WORK","shift_id":"FORK_AM","notes":""},{"mode":"REST","shift_id":null}],[{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"WORK","shift_id":"NIGHT","notes":""},{"mode":"REST","shift_id":null},{"mode":"REST","shift_id":null}]]}}]'::jsonb;late jsonb:='{"id":"CHECK_PM_15","name":"2º turno · entrada às 15h para descanso","segments":[{"start":"15:00","end":"23:00"}],"break_minutes":60}'::jsonb;
begin
 for r in select * from public.escala_warehouse_settings for update loop
  c:=jsonb_set(r.config,'{qlp}','{"weekdays":{},"dates":{}}'::jsonb);shifts:='[]';
  for s in select value from jsonb_array_elements(c->'shifts') loop
   if (s->>'id'='CHECK_AM' and s->'segments'='[{"start":"06:00","end":"16:00"}]'::jsonb or s->>'id'='FORK_AM' and s->'segments'='[{"start":"07:00","end":"17:00"}]'::jsonb) and (s->>'break_minutes')::int in(60,120) and coalesce(s->>'break_start','12:00') in('','12:00') then s:=s||jsonb_build_object('break_minutes',120,'break_start','12:00');end if;
   shifts:=shifts||jsonb_build_array(s);
  end loop;
  if exists(select 1 from jsonb_each(c->'people') x where x.value=patches->2->'before') and not exists(select 1 from jsonb_array_elements(shifts) x where x->>'id'='CHECK_PM_15') then shifts:=shifts||jsonb_build_array(late);end if;
  c:=jsonb_set(c,'{shifts}',shifts);
  for p in select * from jsonb_each(c->'people') loop
   for patch in select value from jsonb_array_elements(patches) loop if p.value=patch->'before' and (patch is distinct from patches->2 or exists(select 1 from jsonb_array_elements(shifts) x where x->>'id'='CHECK_PM_15' and x->'segments'=late->'segments' and x->>'break_minutes'=late->>'break_minutes')) then c:=jsonb_set(c,array['people',p.key],patch->'after');end if;end loop;
  end loop;
  if c is distinct from r.config then
   if position('Correção técnica 2026-11-27' in coalesce(c->>'notes',''))=0 then c:=jsonb_set(c,'{notes}',to_jsonb(coalesce(c->>'notes','')||E'
Correção técnica 2026-11-27: intervalo diurno confirmado 12h–14h; revisão das trocas de turno e retirada do QLP do Armazém.'));end if;
   perform escala_private.warehouse_validate_config(r.unit,c);
   update public.escala_warehouse_settings set config=c,revision=revision+1,updated_at=now() where unit=r.unit returning * into updated;
  end if;
 end loop;
end;
$fix$;
notify pgrst,'reload schema';
